// DUPLICATE GUARD: Check if this reply was already sent to this lead
// Pulls last 3 outbound messages and compares against current reply
// If match found → return empty (stops the chain)

const input = $input.first().json;

// Get the reply text we're about to send
let replyText = '';
try {
  // Try different possible fields for the reply text
  replyText = input.output || input.reply || input.text || '';
} catch(e) {
  replyText = '';
}

if (!replyText) {
  // No reply to send, pass through
  return [{ json: input }];
}

// Get last 3 outbound messages from the API call
let recentOutbounds = [];
try {
  const messagesData = $('Get Last 5 Messages1').first().json;
  const allMessages = messagesData.data || [];
  recentOutbounds = allMessages
    .filter(m => m.direction === 'outbound')
    .slice(0, 3)
    .map(m => (m.text || '').toLowerCase().trim());
} catch (e) {
  // If we can't get messages, allow send (fail open)
  return [{ json: { ...input, dedupPassed: true } }];
}

const currentReply = replyText.toLowerCase().trim();

// Similarity function
const similarity = (a, b) => {
  if (!a || !b) return 0;
  const longer = a.length > b.length ? a : b;
  const shorter = a.length > b.length ? b : a;
  if (longer.length === 0) return 1.0;
  const matrix = [];
  for (let i = 0; i <= shorter.length; i++) matrix[i] = [i];
  for (let j = 0; j <= longer.length; j++) matrix[0][j] = j;
  for (let i = 1; i <= shorter.length; i++) {
    for (let j = 1; j <= longer.length; j++) {
      if (shorter.charAt(i - 1) === longer.charAt(j - 1)) {
        matrix[i][j] = matrix[i - 1][j - 1];
      } else {
        matrix[i][j] = Math.min(matrix[i - 1][j - 1] + 1, matrix[i][j - 1] + 1, matrix[i - 1][j] + 1);
      }
    }
  }
  return (longer.length - matrix[shorter.length][longer.length]) / longer.length;
};

// Check against last 3 outbound messages
for (const prevOutbound of recentOutbounds) {
  if (!prevOutbound) continue;

  // Exact match
  if (currentReply === prevOutbound) {
    return [{ json: { blocked: true, reason: 'DUPLICATE: Exact match with sent message', originalReply: replyText } }];
  }

  // Same opening (first 30 chars)
  if (currentReply.substring(0, 30).length >= 25 && currentReply.substring(0, 30) === prevOutbound.substring(0, 30)) {
    return [{ json: { blocked: true, reason: 'DUPLICATE: Same opening as sent message', originalReply: replyText } }];
  }

  // 75% similar
  const sim = similarity(currentReply, prevOutbound);
  if (sim > 0.75) {
    return [{ json: { blocked: true, reason: 'DUPLICATE: ' + Math.round(sim*100) + '% similar to sent message', originalReply: replyText } }];
  }
}

// No duplicate found - pass through
return [{ json: { ...input, dedupPassed: true } }];

