// Build conversation context for AI with SMART hard stop logic
// FIXED: Price within market range = WARM LEAD, phone request overrides DNC
// Hard stop ONLY if CURRENT message has stop phrase AND no engagement signals
const inputData = $input.first().json;
const messages = inputData.data || [];

let leadData;
try {
  leadData = $('Get Lead data').first().json;
} catch (e) {
  try {
    leadData = $('Get Lead data').first().json;
  } catch (e2) {
    leadData = inputData;
  }
}

let webhookData;
try {
  webhookData = $('Parse Webhook').first().json;
} catch (e) {
  try {
    webhookData = $('Parse Webhook').first().json;
  } catch (e2) {
    const latestMessage = messages[0] || {};
    webhookData = {
      leadId: latestMessage.lead_id || inputData.lead_id || '',
      contactId: latestMessage.contact_id || inputData.contact_id || '',
      senderPhone: latestMessage.remote_phone || inputData.remote_phone || '',
      messageText: latestMessage.text || inputData.text || '',
      isHostile: inputData.isHostile || false,
      isWrongPerson: inputData.isWrongPerson || false
    };
  }
}

const leadType = leadData.custom?.['Lead Type']?.[0] || leadData.custom?.cf_lead_type || 'Unknown';
const propertyAddress = leadData.custom?.['Property Address'] || leadData.custom?.cf_BT2tCruHpFRG8IyUXao1H5EcTMTpAYKVJHM3eTcSG7j || '';
const propertyCity = leadData.custom?.['Property City'] || leadData.custom?.cf_property_city || '';
const distressTypes = leadData.custom?.['Distress Types'] || leadData.custom?.cf_distress_types || '';
const leadName = leadData.display_name || '';

// Get Market Type and Estimated Value (ARV) for price comparison
const marketType = leadData.custom?.['Market Type']?.[0] || leadData.custom?.cf_market_type || 'Unknown';
const estimatedValue = parseFloat(leadData.custom?.['Estimated Value'] || leadData.custom?.cf_estimated_value || leadData.custom?.cf_pACEQevqALObdrUCiXUbFRmO1HdJzhsbIBjcW7Aomen || 0);

// Get Campaign Type fields for expired listing support
const campaignType = leadData.custom?.['Campaign Type']?.[0] || leadData.custom?.cf_809dloIbQGtxHtuA7rms0Aaem3Os2PPcVkNN40a58CR || 'distressed';
const expiredTier = leadData.custom?.['Expired Tier']?.[0] || leadData.custom?.cf_LUpXNPXlxgGX6fgWDwb8jEraSdzdOTYSJoqereIakp6 || null;
const listingExpiredDate = leadData.custom?.['Listing Expired Date'] || leadData.custom?.cf_8ozTEtU4jw4QcgFkQl066Z1oHudqOO0BJKcoC9RebIs || null;
const listingPrice = parseFloat(leadData.custom?.['Listing Price'] || leadData.custom?.cf_teyxHlFGUb52AY4AqFQ8CdZvDYuvrOA6zY0hSMDbLpt || 0);
const daysOnMarket = parseInt(leadData.custom?.['Days on Market'] || leadData.custom?.cf_okCLnBnSnCKviXYNwbYcVxPQaZX3CFEPPPlA9OQUT04 || 0);
const isExpiredLead = campaignType === 'expired';

// CORRECT Price ranges by market type:
// BRRRR: $30k-$200k (target market)
// High_ARV: $200k-$400k (target market)
// If asking price is WITHIN market range = WARM LEAD (engaged!)
// If asking price > 2x ARV = ridiculous/joke

const missingFields = [];
const warnings = [];

if (!propertyAddress || propertyAddress === 'Not specified') {
  missingFields.push('Property Address');
}

if (!leadName || leadName === 'Unknown') {
  warnings.push('Lead Name missing - using generic greeting');
}

const currentMessage = webhookData.messageText || messages[0]?.text || '';
if (!currentMessage) {
  missingFields.push('Current Message');
}

// BUILD CONVERSATION HISTORY
let conversationHistory = 'No previous messages';
if (messages && messages.length > 0) {
  const formattedMessages = [];
  for (let i = 0; i < Math.min(messages.length, 20); i++) {
    const msg = messages[messages.length - 1 - i];
    const direction = msg.direction === 'outbound' ? 'You' : 'Them';
    const text = msg.text || '';
    formattedMessages.push(direction + ': ' + text);
  }
  conversationHistory = formattedMessages.join('\n');
}

const currentLower = currentMessage.toLowerCase();

// =====================================================
// PHONE REQUEST DETECTION - HIGHEST PRIORITY
// If they say "call me" or "call now" = PHONE_REQUEST
// This OVERRIDES any soft DNC language!
// =====================================================
const phoneRequestPhrases = [
  'call me', 'call now', 'give me a call', 'can you call',
  'call if you', 'call when', 'please call', 'want to call',
  'ring me', 'phone me', 'hit me up', 'reach out'
];

let phoneRequestDetected = false;
for (const phrase of phoneRequestPhrases) {
  if (currentLower.includes(phrase)) {
    phoneRequestDetected = true;
    break;
  }
}

// =====================================================
// PRICE EXTRACTION - Check BEFORE DNC logic
// =====================================================
function extractPrice(text) {
  const cleanText = text.toLowerCase().replace(/,/g, '');

  const millionMatch = cleanText.match(/(\d+(?:\.\d+)?)\s*(?:m|mil|million)/i);
  if (millionMatch) return parseFloat(millionMatch[1]) * 1000000;

  const thousandMatch = cleanText.match(/(\d+(?:\.\d+)?)\s*(?:k|thousand)/i);
  if (thousandMatch) return parseFloat(thousandMatch[1]) * 1000;

  const rawMatch = cleanText.match(/\$?\s*(\d{4,})/);
  if (rawMatch) return parseFloat(rawMatch[1]);

  return null;
}

let askingPrice = extractPrice(currentMessage);
let priceInMarketRange = false;
let ridiculousPrice = false;
let priceToArvRatio = null;

// PRICE CHECK - ARV comparison is MOST IMPORTANT
// Rule: Price must be AT or BELOW ARV to be warm lead
// Above ARV = not warm (need negotiate). 2x+ ARV = ridiculous joke
if (askingPrice && estimatedValue > 0) {
  priceToArvRatio = askingPrice / estimatedValue;

  // RIDICULOUS: 2x+ ARV = joke price, they think we are a bot
  if (priceToArvRatio >= 2.0) {
    ridiculousPrice = true;
    priceInMarketRange = false;
    warnings.push('RIDICULOUS JOKE PRICE: $' + askingPrice.toLocaleString() + ' is ' + (priceToArvRatio * 100).toFixed(0) + '% of ARV $' + estimatedValue.toLocaleString() + ' - FUNNY RESPONSE NEEDED');
  }
  // ABOVE ARV: not warm lead, need to negotiate down
  else if (priceToArvRatio > 1.0) {
    priceInMarketRange = false;
    warnings.push('ABOVE ARV: $' + askingPrice.toLocaleString() + ' > ARV $' + estimatedValue.toLocaleString() + ' - NOT warm lead');
  }
  // AT OR BELOW ARV: good price = warm lead
  else {
    priceInMarketRange = true;
    warnings.push('GOOD PRICE: $' + askingPrice.toLocaleString() + ' <= ARV $' + estimatedValue.toLocaleString() + ' - WARM LEAD');
  }
}
// No ARV available - check market range only
else if (askingPrice) {
  if (marketType === 'BRRRR' && askingPrice >= 30000 && askingPrice <= 200000) {
    priceInMarketRange = true;
    warnings.push('PRICE IN BRRRR RANGE: $' + askingPrice.toLocaleString());
  }
  else if (marketType === 'High_ARV' && askingPrice >= 200000 && askingPrice <= 400000) {
    priceInMarketRange = true;
    warnings.push('PRICE IN HIGH_ARV RANGE: $' + askingPrice.toLocaleString());
  }
  else {
    priceInMarketRange = false;
    ridiculousPrice = askingPrice > 400000;
    warnings.push('OUT OF RANGE: $' + askingPrice.toLocaleString());
  }
}

// =====================================================
// CONDITIONAL DNC DETECTION
// "if you dont want to pay X, dont contact me" = NOT real DNC
// =====================================================
const conditionalPhrases = [
  'if you do not', 'if you dont', 'if u dont', 'if u do not',
  'if you are not', 'if you arent', 'if youre not',
  'unless you', 'otherwise dont'
];

let hasConditionalLanguage = false;
for (const phrase of conditionalPhrases) {
  if (currentLower.includes(phrase)) {
    hasConditionalLanguage = true;
    break;
  }
}

// =====================================================
// ENGAGEMENT SIGNALS - These override soft DNC
// =====================================================
let hasEngagementSignal = phoneRequestDetected || priceInMarketRange || hasConditionalLanguage;

if (hasEngagementSignal) {
  warnings.push('ENGAGEMENT DETECTED: ' + 
    (phoneRequestDetected ? 'Phone request ' : '') +
    (priceInMarketRange ? 'Price in range ' : '') +
    (hasConditionalLanguage ? 'Conditional language' : ''));
}

// IMMEDIATE HARD STOP phrases - ONLY real DNC, not conditional
const immediateStopPhrases = [
  'leave me alone', 'go away', 'stop texting', 'stop contacting',
  'dont text me', 'remove me', 'take me off',
  'fuck off', 'screw you', 'go to hell', 'piss off', 'buzz off',
  'stop messaging', 'quit texting', 'no. go away', 'get lost',
  'dont text me again', 'it will be ugly', 'dont fuck with me',
  'ill call the cops', 'call the police',
  'harassment', 'harassing me', 'sue you', 'lawyer',
  'no means no', 'i said no', 'told you no', 'already said no'
];

// NOTE: Removed 'dont contact me' from hard stop - often conditional

const hostilePhrases = [
  'scammer', 'nice try scammer', 'youre a scammer', 'this is a scam',
  'copy and paste', 'youre a bot', 'youre not real', 'obvious bot',
  'spam', 'spammer', 'reported', 'blocking you',
  'retard', 'idiot', 'moron', 'stupid', 'dumb ass', 'dumbass',
  'fuck you', 'fucking', 'asshole', 'piece of shit', 'pos',
  'get a life', 'loser', 'pathetic', 'creep', 'weirdo',
  'die', 'kill', 'threat', 'i will find you',
  'nigga', 'nigger', 'cracker', 'wetback', 'spic', 'chink'
];

const softRejectionPhrases = [
  'not interested', 'no thanks', 'nope'
];

const addressChallengePhrases = [
  'no such address', 'doesnt exist', 'there is no', 'thats not real',
  'wrong address', 'not a real address', 'fake address'
];

const propertySoldPhrases = [
  'it sold', 'its sold', 'house sold', 'property sold', 'already sold',
  'i sold it', 'we sold it', 'sold the house', 'sold the property',
  'that one sold', 'this house sold', 'been sold'
];

const wrongPersonPhrases = [
  'wrong number', 'wrong person', 'not my property', 'not my house',
  'dont own', 'i dont own', 'thats not me', 'its not mine', 'not mine',
  'you have the wrong', 'got the wrong', 'isnt my', 'is not my'
];

let softRejectionCount = 0;
let hostileCount = 0;
let addressChallengeDetected = false;
let propertySoldDetected = false;
let wrongPersonDetected = false;
let hardStop = false;
let hardStopReason = '';
let previousStopDetected = false;

// Property sold detection
let propertySoldEarly = false;
for (const phrase of propertySoldPhrases) {
  if (currentLower.includes(phrase)) {
    propertySoldEarly = true;
    propertySoldDetected = true;
    break;
  }
}

// CHECK 1: Immediate stop phrases - BUT NOT if engagement signals present
if (!hasEngagementSignal) {
  for (const phrase of immediateStopPhrases) {
    if (currentLower.includes(phrase)) {
      if (propertySoldEarly) break;
      hardStop = true;
      hardStopReason = 'CURRENT MESSAGE STOP: ' + phrase;
      break;
    }
  }
}

// CHECK 2: Hostile phrases - BUT NOT if engagement signals present
if (!hardStop && !hasEngagementSignal) {
  for (const phrase of hostilePhrases) {
    if (currentLower.includes(phrase)) {
      hostileCount++;
      hardStop = true;
      hardStopReason = 'CURRENT MESSAGE HOSTILE: ' + phrase;
      break;
    }
  }
}

// CHECK 3: Address challenge
for (const phrase of addressChallengePhrases) {
  if (currentLower.includes(phrase)) {
    addressChallengeDetected = true;
    break;
  }
}

// CHECK 4: Wrong person
for (const phrase of wrongPersonPhrases) {
  if (currentLower.includes(phrase)) {
    wrongPersonDetected = true;
    break;
  }
}

// CHECK 5: Soft rejection - BUT NOT if engagement signals present
if (!propertySoldDetected && !hasEngagementSignal) {
  for (const phrase of softRejectionPhrases) {
    if (currentLower.includes(phrase)) {
      softRejectionCount++;
      break;
    }
  }
}

// CHECK 6: History analysis (warnings only)
const inboundMessages = messages.filter(m => m.direction === 'inbound');
let historicalRejectionCount = 0;

for (const msg of inboundMessages) {
  const text = (msg.text || '').toLowerCase();
  for (const phrase of immediateStopPhrases) {
    if (text.includes(phrase)) { previousStopDetected = true; break; }
  }
  for (const phrase of hostilePhrases) {
    if (text.includes(phrase)) { previousStopDetected = true; break; }
  }
  for (const phrase of softRejectionPhrases) {
    if (text.includes(phrase)) { historicalRejectionCount++; break; }
  }
}

if (historicalRejectionCount > 0 && softRejectionCount === 0) {
  warnings.push('Lead previously rejected (' + historicalRejectionCount + ' times) but is now re-engaging');
}

// CHECK 7: Soft rejection to hard stop - BUT NOT if engagement signals
if (!hardStop && softRejectionCount >= 1 && !hasEngagementSignal) {
  hardStop = true;
  hardStopReason = 'Explicit rejection in CURRENT message';
}

if (previousStopDetected && !hardStop) {
  warnings.push('Lead previously was hostile but is now re-engaging - proceed with caution');
}

// FINAL: If engagement signal present, CLEAR hard stop
if (hasEngagementSignal && hardStop) {
  warnings.push('OVERRIDE: Engagement signal detected, clearing hard stop. Reason was: ' + hardStopReason);
  hardStop = false;
  hardStopReason = '';
}

if (missingFields.length > 0) {
  return [{
    json: {
      error: true,
      missingFields: missingFields,
      warnings: warnings,
      reason: 'Cannot generate AI response - missing: ' + missingFields.join(', '),
      skipAI: true,
      fallbackResponse: 'hey can you tell me more about your situation',
      leadId: webhookData.leadId || '',
      senderPhone: webhookData.senderPhone || '',
      messageText: currentMessage,
      hardStop: false,
      conversationHistory: conversationHistory
    }
  }];
}

const result = {
  validated: true,
  warnings: warnings,
  leadId: webhookData.leadId || '',
  contactId: webhookData.contactId || '',
  senderPhone: webhookData.senderPhone || '',
  messageText: currentMessage,
  isHostile: webhookData.isHostile || hostileCount > 0,
  isWrongPerson: webhookData.isWrongPerson || wrongPersonDetected,
  leadType: leadType,
  propertyAddress: propertyAddress,
  propertyCity: propertyCity || 'the area',
  distressTypes: distressTypes || 'Not specified',
  leadName: leadName || 'there',
  conversationHistory: conversationHistory,
  groundingInstructions: 'CRITICAL: Only use these EXACT values: Property: ' + propertyAddress + ', City: ' + (propertyCity || 'the area') + ', Lead Name: ' + (leadName || 'there') + '. NEVER invent addresses, prices, or details not in the conversation.',
  rejectionCount: softRejectionCount,
  hostileCount: hostileCount,
  addressChallengeDetected: addressChallengeDetected,
  propertySoldDetected: propertySoldDetected,
  wrongPersonDetected: wrongPersonDetected,
  hardStop: hardStop,
  hardStopReason: hardStopReason,
  previousStopDetected: previousStopDetected,
  // Price comparison fields
  marketType: marketType,
  estimatedValue: estimatedValue,
  askingPrice: askingPrice,
  priceToArvRatio: priceToArvRatio,
  priceInMarketRange: priceInMarketRange,
  ridiculousPrice: ridiculousPrice,
  // NEW: Engagement detection fields
  phoneRequestDetected: phoneRequestDetected,
  hasConditionalLanguage: hasConditionalLanguage,
  hasEngagementSignal: hasEngagementSignal,
  // Campaign type fields (expired listing support)
  campaignType: campaignType,
  isExpiredLead: isExpiredLead,
  expiredTier: expiredTier,
  listingExpiredDate: listingExpiredDate,
  listingPrice: listingPrice,
  daysOnMarket: daysOnMarket
};

return [{ json: result }];

