parameters.jsCode:
const data = $input.first().json;
const eventData = data.body?.event?.data || data;

const smsData = {
  leadId: eventData.lead_id,
  contactId: eventData.contact_id,
  senderPhone: eventData.remote_phone,
  messageText: eventData.text || '',
  direction: eventData.direction || 'inbound',
  timestamp: eventData.date_created || new Date().toISOString()
};

if (smsData.direction !== 'inbound') {
  return [];
}

const messageLC = String(smsData.messageText).toLowerCase().trim();

// =====================================================
// PRICE EXTRACTION - Extract but DON'T auto-classify
// Let Build AI Context2 check against ARV/market range
// =====================================================

function extractPrice(text) {
  const cleanText = text.toLowerCase().replace(/,/g, '');

  // Check for million (e.g., "4 million", "4m", "4 mil")
  const millionMatch = cleanText.match(/(\d+(?:\.\d+)?)\s*(?:m|mil|million)/i);
  if (millionMatch) return parseFloat(millionMatch[1]) * 1000000;

  // Check for thousand (e.g., "150k", "150 thousand")
  const thousandMatch = cleanText.match(/(\d+(?:\.\d+)?)\s*(?:k|thousand)/i);
  if (thousandMatch) return parseFloat(thousandMatch[1]) * 1000;

  // Check for dollar amounts (e.g., "$599,000", "599000")
  const dollarMatch = cleanText.match(/\$\s*(\d+)/);
  if (dollarMatch) return parseFloat(dollarMatch[1]);

  // Check for raw numbers 5+ digits (e.g., "599000", "150000")
  const rawMatch = cleanText.match(/\b(\d{5,})\b/);
  if (rawMatch) return parseFloat(rawMatch[1]);

  return null;
}

const detectedPrice = extractPrice(messageLC);
const hasPricePattern = detectedPrice !== null;

// =====================================================
// ENGAGEMENT SIGNALS - CHECK FIRST (OVERRIDE DNC)
// =====================================================

// Phone request phrases - if they say "call me" = NOT DNC!
const phoneRequestPhrases = [
  'call me', 'call now', 'give me a call', 'can you call',
  'call if you', 'call when', 'please call', 'want to call',
  'ring me', 'phone me'
];

// Conditional language - "if you dont want X, dont contact" = NOT real DNC!
const conditionalPhrases = [
  'if you do not', 'if you dont', 'if u dont', 'if u do not',
  'if you are not', 'if you arent', 'if youre not',
  'unless you', 'otherwise dont'
];

// Multiple properties / acreage - HOT LEAD signals!
const multiplePropertyPhrases = [
  'acres for sale', 'acre for sale', 'multiple properties',
  'closing on', 'also have', 'another property',
  'multiple lots', 'several properties', 'have a few',
  'few properties', 'couple properties', 'other property'
];

// Seller finance history - HOT LEAD signals!
const sellerFinancePhrases = [
  'carried it', 'seller financed', 'owner financed',
  'held the note', 'carried the note', 'financed it myself',
  'i financed', 'did seller financing', 'owner financing'
];

const hasPhoneRequest = phoneRequestPhrases.some(kw => messageLC.includes(kw));
const hasConditionalLanguage = conditionalPhrases.some(kw => messageLC.includes(kw));
const hasMultipleProperties = multiplePropertyPhrases.some(kw => messageLC.includes(kw));
const hasSellerFinanceHistory = sellerFinancePhrases.some(kw => messageLC.includes(kw));

// Price is engagement BUT needs range check later - still pass through, don't auto-DNC
const hasEngagementSignal = hasPhoneRequest || hasPricePattern || hasConditionalLanguage || hasMultipleProperties || hasSellerFinanceHistory;

// If ANY engagement signal present, SKIP DNC check entirely!
if (hasEngagementSignal) {
  smsData.isOptOut = false;
  smsData.isHostile = false;
  smsData.hasPhoneRequest = hasPhoneRequest;
  smsData.hasPricePattern = hasPricePattern;
  smsData.detectedPrice = detectedPrice;
  smsData.hasConditionalLanguage = hasConditionalLanguage;
  smsData.hasMultipleProperties = hasMultipleProperties;
  smsData.hasSellerFinanceHistory = hasSellerFinanceHistory;
  smsData.hasEngagementSignal = true;
  return [{ json: smsData }];
}

// =====================================================
// DNC KEYWORDS - Only if NO engagement signals
// =====================================================

// REMOVED 'end' - too common in normal phrases like "end of next week"
const exactMatchKeywords = [
  'stop',
  'quit',
  'cancel',
  'remove',
  'block',
  'spam'
];

// ONLY explicit opt-out phrases - NOT conditional statements
const phraseKeywords = [
  'unsubscribe',
  'opt out',
  'optout',
  'remove me',
  'do not text',
  'dont text',
  "don't text",
  'stop texting',
  'stop messaging',
  'take me off',
  'never contact',
  'never contact me',
  'do not ever',
  'do not ever contact',
  'dont ever contact',
  'stop contacting',
  'stop contacting me',
  'please stop',
  'cease and desist',
  'tcpa',
  'this is spam',
  'text me again',
  'txt me again',
  'it will be ugly',
  'dont fuck with me',
  'im not the one',
  'not the one',
  'ill call the cops',
  'call the police',
  'harassment',
  'harassing me',
  'sue you',
  'my lawyer',
  'fucking retard',
  'get a life'
];

const hostileKeywords = [
  'fuck off',
  'fuck you',
  'screw you',
  'go to hell',
  'piss off',
  'get lost',
  'buzz off',
  'leave me the fuck alone'
];

const familyMemberPatterns = [
  "'s son", "'s daughter", "'s husband", "'s wife", "'s brother", "'s sister",
  'im her son', 'im his son', 'im her daughter', 'im his daughter',
  'this is her son', 'this is his son', 'this is her daughter', 'this is his daughter'
];

const questionIndicators = [
  'what place', 'what property', 'which house', 'which property',
  'who is this', 'who are you', 'what is this', 'what do you want', '?'
];

const ignoreAsOptOut = ['no', 'nope', 'no thanks', 'nah', 'not right now', 'not interested'];

function hasExactWord(text, word) {
  const regex = new RegExp(`\\b${word}\\b`, 'i');
  return regex.test(text);
}

const isFamilyMember = familyMemberPatterns.some(kw => messageLC.includes(kw));
const hasQuestion = questionIndicators.some(kw => messageLC.includes(kw));
const isHostile = hostileKeywords.some(kw => messageLC.includes(kw));

if (isFamilyMember) {
  smsData.isOptOut = false;
  smsData.isHostile = false;
  smsData.isFamilyMember = true;
} else if (hasQuestion) {
  smsData.isOptOut = false;
  smsData.isHostile = false;
  smsData.hasQuestion = true;
} else if (isHostile) {
  smsData.isOptOut = false;
  smsData.isHostile = true;
} else if (ignoreAsOptOut.includes(messageLC)) {
  smsData.isOptOut = false;
  smsData.isHostile = false;
} else {
  const exactMatch = exactMatchKeywords.some(kw => hasExactWord(messageLC, kw));
  const phraseMatch = phraseKeywords.some(kw => messageLC.includes(kw));
  smsData.isOptOut = exactMatch || phraseMatch;
  smsData.isHostile = false;
}

smsData.hasEngagementSignal = false;
smsData.detectedPrice = null;
return [{ json: smsData }];


// LAYER 2: OUTPUT VALIDATION v2.0
// Catches: profanity, self-reference errors, robotic questions, duplicates, hallucinations                                                 

const input = $input.first().json;                                                                                                          
const aiReply = input.reply || input.output || input.text || '';
const aiReplyLower = aiReply.toLowerCase();

// Get context from Build AI Context
let conversationHistory = '';
let hardStop = false;
let knownAddress = '';
let knownCity = '';
let addressChallengeDetected = false;
let propertySoldDetected = false;

try {
  const context = $('Build AI Context').first().json;
  conversationHistory = context.conversationHistory || '';
  hardStop = context.hardStop || false;
  knownAddress = context.propertyAddress || '';
  knownCity = context.propertyCity || '';
  addressChallengeDetected = context.addressChallengeDetected || false;
  propertySoldDetected = context.propertySoldDetected || false;
} catch (e) {
  conversationHistory = input.conversationHistory || '';
  hardStop = input.hardStop || false;
  knownAddress = input.propertyAddress || '';
  knownCity = input.propertyCity || '';
  addressChallengeDetected = input.addressChallengeDetected || false;
  propertySoldDetected = input.propertySoldDetected || false;
}

const issues = [];

// =====================================================
// CHECK 0: PROFANITY/VULGAR CONTENT FILTER (CRITICAL!)
// AI should NEVER generate vulgar, offensive, or inappropriate content
// =====================================================
const profanityPatterns = [
  'fuck', 'shit', 'ass ', 'asshole', 'bitch', 'damn', 'crap',
  'dick', 'cock', 'pussy', 'cunt', 'whore', 'slut',
  'bastard', 'piss', 'retard', 'fag', 'nigger', 'nigga',
  'eat a dick', 'suck my', 'go to hell', 'kill yourself',
  'kys', 'stfu', 'gtfo'
];

for (const profanity of profanityPatterns) {
  if (aiReplyLower.includes(profanity)) {
    return [{ json: {
      validated: false,
      issues: ['PROFANITY_BLOCKED: AI generated vulgar content - "' + profanity + '"'],
      originalReply: aiReply,
      reply: '',
      skipSend: true,
      profanityBlocked: true,
      reason: 'AI generated inappropriate content containing: ' + profanity
    } }];
  }
}

// =====================================================
// CHECK 0.5: SELF-REFERENCE CHECK (CRITICAL!)
// Rey is OUR persona - we should NEVER ask about Rey's info
// Bad: "What's the last name Rey?" "Who is Rey?" "Rey's number?"
// =====================================================
const selfReferencePatterns = [
  'last name rey', 'rey\'s last name', 'reys last name',
  'who is rey', 'who\'s rey', 'whos rey',
  'rey\'s number', 'reys number', 'rey\'s phone', 'reys phone',
  'call rey', 'text rey', 'contact rey',
  'what\'s rey', 'whats rey', 'about rey',
  'is rey', 'does rey', 'can rey'
];

for (const pattern of selfReferencePatterns) {
  if (aiReplyLower.includes(pattern)) {
    return [{ json: {
      validated: false,
      issues: ['SELF_REFERENCE_ERROR: AI confused about identity - asking about Rey who is OUR persona'],
      originalReply: aiReply,
      reply: 'hey whats up',
      usedFallback: true,
      skipSend: false,
      selfReferenceError: true
    } }];
  }
}

// =====================================================
// CHECK 0.6: ROBOTIC QUESTION DETECTION
// Avoid overly formal/robotic questions that sound like a survey
// =====================================================
const roboticPatterns = [
  'what\'s your last name',
  'whats your last name',
  'what is your last name',
  'what is your full name',
  'i\'ll see if anyone knows you',
  'ill see if anyone knows you',
  'is this a personal or business',
  'how do you feel about random',
  'please provide your',
  'could you please',
  'may i ask',
  'can you verify',
  'for verification purposes',
  'would you mind telling me',
  'i need to verify',
  'can you confirm your'
];

for (const pattern of roboticPatterns) {
  if (aiReplyLower.includes(pattern)) {
    issues.push('ROBOTIC_QUESTION: AI generated formal/robotic question');
    break;
  }
}

// =====================================================
// CHECK 0.7: MULTIPLE QUESTIONS CHECK
// AI should only ask ONE question per message
// =====================================================
const questionMarks = (aiReply.match(/\?/g) || []).length;
if (questionMarks > 1) {
  issues.push('MULTIPLE_QUESTIONS: AI asked ' + questionMarks + ' questions (max 1)');
}

// Check for hard stop flag
if (hardStop) {
  return [{ json: {
    validated: false,
    issues: ['HARD_STOP: Explicit rejection in thread'],
    originalReply: aiReply,
    reply: '',
    skipSend: true,
    hardStop: true
  } }];
}

// ADDRESS CHALLENGE HANDLING
if (addressChallengeDetected) {
  const addressChallengeResponses = [
    'oh my bad. got some bad info. sorry abt that',
    'ah shoot. must have wrong info. sorry to bug u',
    'my bad. do u own property in the area tho'
  ];
  const randomResponse = addressChallengeResponses[Math.floor(Math.random() * addressChallengeResponses.length)];
  return [{ json: {
    validated: false,
    issues: ['ADDRESS_CHALLENGE: Using fixed clarification response'],
    originalReply: aiReply,
    reply: randomResponse,
    usedFallback: true,
    skipSend: false,
    addressChallengeHandled: true
  } }];
}

// PROPERTY SOLD HANDLING
if (propertySoldDetected) {
  const propertySoldResponses = [
    'oh nice congrats! do u have any other properties ud consider selling',
    'gotcha! any other properties u might wanna sell',
    'ah ok! got any other places ud consider selling'
  ];
  const randomResponse = propertySoldResponses[Math.floor(Math.random() * propertySoldResponses.length)];
  return [{ json: {
    validated: false,
    issues: ['PROPERTY_SOLD: Acknowledging and asking about other properties'],
    originalReply: aiReply,
    reply: randomResponse,
    usedFallback: true,
    skipSend: false,
    propertySoldHandled: true
  } }];
}

// =====================================================
// DUPLICATE CHECK: Compare AI reply against last 2-3 outbound messages
// =====================================================
let recentOutbounds = [];

try {
  const messagesData = $('Get Last 5 Messages1').first().json;
  const allMessages = messagesData.data || [];
  recentOutbounds = allMessages
    .filter(m => m.direction === 'outbound')
    .slice(0, 3)
    .map(m => (m.text || '').toLowerCase().trim());
} catch (e) {
  if (conversationHistory && conversationHistory !== 'No previous messages') {
    const lines = conversationHistory.split(/\n/);
    for (const line of lines) {
      const trimmed = line.trim();
      if (trimmed.startsWith('You:')) {
        const msgText = trimmed.replace(/^You:\s*/i, '').trim().toLowerCase();
        if (msgText) recentOutbounds.push(msgText);
        if (recentOutbounds.length >= 3) break;
      }
    }
  }
}

const currentReply = aiReplyLower.trim();

// Similarity function for near-duplicate detection
const similarity = (a, b) => {
  if (!a || !b) return 0;
  a = a.toLowerCase();
  b = b.toLowerCase();
  const longer = a.length > b.length ? a : b;
  const shorter = a.length > b.length ? b : a;
  if (longer.length === 0) return 1.0;
  const matrix = [];
  for (let i = 0; i <= shorter.length; i++) matrix[i] = [i];
  for (let j = 0; j <= longer.length; j++) matrix[0][j] = j;
  for (let i = 1; i <= shorter.length; i++) {
    for (let j = 1; j <= longer.length; j++) {
      if (shorter.charAt(i - 1) === longer.charAt(j - 1)) {
        matrix[i][j] = matrix[i - 1][j - 1];
      } else {
        matrix[i][j] = Math.min(matrix[i - 1][j - 1] + 1, matrix[i][j - 1] + 1, matrix[i - 1][j] + 1);
      }
    }
  }
  return (longer.length - matrix[shorter.length][longer.length]) / longer.length;
};

if (recentOutbounds.length > 0 && currentReply) {
  for (const prevOutbound of recentOutbounds) {
    if (!prevOutbound) continue;

    if (currentReply === prevOutbound) {
      issues.push('DUPLICATE: AI reply matches previously sent message exactly');
      break;
    }

    const currentStart = currentReply.substring(0, 35);
    const prevStart = prevOutbound.substring(0, 35);
    if (currentStart.length >= 25 && currentStart === prevStart) {
      issues.push('REPEAT: AI reply starts the same as a previously sent message');
      break;
    }

    const sim = similarity(currentReply, prevOutbound);
    if (sim > 0.75) {
      issues.push('NEAR_DUPLICATE: AI reply is ' + Math.round(sim * 100) + '% similar to a sent message');
      break;
    }

    if (currentReply.includes('hey its rey') && prevOutbound.includes('hey its rey')) {
      issues.push('REPEAT: Reusing intro phrase from previous message');
      break;
    }
  }
}

if (issues.length > 0 && issues.some(i => i.includes('DUPLICATE') || i.includes('REPEAT') || i.includes('NEAR_DUPLICATE'))) {
  return [{ json: {
    validated: false,
    issues: issues,
    originalReply: aiReply,
    reply: '',
    skipSend: true,
    isDuplicate: true,
    recentOutbounds: recentOutbounds.length,
    reason: 'AI generated same reply we already sent - blocking'
  } }];
}

// Check for invented addresses
const addressPattern = /\d+\s+\w+\s+(street|st|road|rd|avenue|ave|boulevard|blvd|drive|dr|lane|ln|court|ct|way|circle|cir)/i;
const foundAddress = aiReply.match(addressPattern);
if (foundAddress && knownAddress) {
  const mentionedAddr = foundAddress[0].toLowerCase();
  const knownAddrLower = knownAddress.toLowerCase();
  const addrNumber = mentionedAddr.match(/^\d+/);
  if (addrNumber && !knownAddrLower.includes(addrNumber[0])) {
    issues.push('Hallucinated address: ' + foundAddress[0]);
  }
}

// Check for over-specificity
const landmarkPattern = /few blocks from|near|close to|by the|across from/i;
if (landmarkPattern.test(aiReply) && recentOutbounds.length < 3) {
  issues.push('OVER_SPECIFIC: Mentioning landmarks too early');
}

// Check for forbidden carrier words
const bannedWords = ['investor', 'investment', 'cash buyer', 'motivated seller', 'real estate', 'wholesale'];
for (const word of bannedWords) {
  if (aiReplyLower.includes(word)) issues.push('Carrier-banned word: ' + word);
}

// Check for unauthorized promises
const forbiddenPhrases = ['i guarantee', 'we guarantee', 'guaranteed', 'i promise', 'we will definitely', 'no fees ever'];
for (const phrase of forbiddenPhrases) {
  if (aiReplyLower.includes(phrase)) issues.push('Unauthorized promise: ' + phrase);
}

// Check message length
if (aiReply.length > 160) issues.push('Message too long: ' + aiReply.length + ' chars');

// Check for empty response
if (!aiReply || aiReply.trim().length === 0) issues.push('Empty response from AI');

// Non-duplicate issues: use fallback reply
if (issues.length > 0) {
  const isOverSpecific = issues.some(i => i.includes('OVER_SPECIFIC'));
  const isRobotic = issues.some(i => i.includes('ROBOTIC_QUESTION'));
  const isMultiQuestion = issues.some(i => i.includes('MULTIPLE_QUESTIONS'));

  let fallbackReply = 'hey can you tell me more about your situation';
  if (isOverSpecific) fallbackReply = 'hey i buy houses in the area. ever think abt selling urs';
  if (isRobotic || isMultiQuestion) fallbackReply = 'hey whats up';

  return [{ json: {
    validated: false,
    issues: issues,
    originalReply: aiReply,
    reply: fallbackReply,
    usedFallback: true,
    skipSend: false,
    recentOutbounds: recentOutbounds.length
  } }];
}

return [{ json: {
  validated: true,
  issues: [],
  reply: aiReply,
  usedFallback: false,
  skipSend: false,
  recentOutbounds: recentOutbounds.length
} }];

