// Check if lead is HUMAN HAND and if 13 days have passed
const HUMAN_HAND_STATUS_ID = 'stat_AVA3WALf67nRg7DZXeNckA5RS0ifVRtcBJqeReNs9D6';
const BLOCK_DAYS = 13;

const leadData = $input.first().json;
const statusId = leadData.status_id;
const dateUpdated = leadData.date_updated;

// If not HUMAN HAND, allow AI to reply
if (statusId !== HUMAN_HAND_STATUS_ID) {
  return [{ json: { ...leadData, allowAIReply: true, reason: 'Not Human Hand status' } }];
}

// If HUMAN HAND, check if 13 days have passed
if (dateUpdated) {
  const statusChangeDate = new Date(dateUpdated);
  const now = new Date();
  const daysSinceChange = Math.floor((now - statusChangeDate) / (1000 * 60 * 60 * 24));

  if (daysSinceChange >= BLOCK_DAYS) {
    // 13+ days passed - AI can reply again
    return [{ json: { ...leadData, allowAIReply: true, daysSinceHumanHand: daysSinceChange, reason: '13+ days passed since Human Hand' } }];
  } else {
    // Still within 13 days - block AI reply
    return [{ json: { ...leadData, allowAIReply: false, daysSinceHumanHand: daysSinceChange, daysRemaining: BLOCK_DAYS - daysSinceChange, reason: 'Human Hand - AI blocked for ' + (BLOCK_DAYS - daysSinceChange) + ' more days' } }];
  }
} else {
  // No date_updated - block to be safe
  return [{ json: { ...leadData, allowAIReply: false, reason: 'Human Hand - no date_updated found' } }];
}

// Thompson Sampling Feedback - Fixed version
// 1. Get template_id from last outbound message
// 2. Map classification to valid response_type
// 3. Call /api/template-response with correct params

const CONVEX_URL = 'https://YOUR_CONVEX_DEPLOYMENT.convex.site';

// Get data from previous nodes
let classification;
let phone;
let leadId;

try {
  classification = $('Lead Identify').first().json.output;
} catch (e) {
  classification = $input.first().json.output || 'UNKNOWN';
}

try {
  phone = $('Build AI Context').first().json.senderPhone;
  leadId = $('Build AI Context').first().json.leadId;
} catch (e) {
  phone = null;
  leadId = null;
}

if (!phone) {
  return [{ json: { success: false, error: 'No phone number available', classification } }];
}

// Map classification to response_type
const POSITIVE_CLASSIFICATIONS = [
  'HOT_LEAD_SELLER', 'WARM_LEAD', 'INTERESTED', 'PHONE_REQUEST',
  'READY_TO_SELL', 'PRICE_DISCLOSED', 'MEETING_REQUEST', 'CALLBACK_REQUEST',
  'INTERESTED_FUTURE', 'PUSHBACK_ENGAGED', 'INFO_GATHERING'
];

const NEGATIVE_CLASSIFICATIONS = [
  'NOT_INTERESTED', 'OBJECTION', 'PRICE_OBJECTION', 'REALTOR_OBJECTION',
  'NOT_FOR_SALE', 'COLD_LEAD', 'CONVERSATION_END'
];

const DNC_CLASSIFICATIONS = [
  'DNC_REQUESTED', 'HOSTILE', 'THREAT', 'STOP', 'REMOVE'
];

const CONVERSION_CLASSIFICATIONS = [
  'MEETING_SCHEDULED', 'DEAL_DISCUSSED', 'CONTRACT_SENT'
];

let response_type = 'neutral'; // default

if (POSITIVE_CLASSIFICATIONS.includes(classification)) {
  response_type = 'positive';
} else if (NEGATIVE_CLASSIFICATIONS.includes(classification)) {
  response_type = 'negative';
} else if (DNC_CLASSIFICATIONS.includes(classification)) {
  response_type = 'dnc';
} else if (CONVERSION_CLASSIFICATIONS.includes(classification)) {
  response_type = 'conversion';
}

// Fetch last outbound template_id
let template_id = null;
try {
  const lastOutbound = await this.helpers.httpRequest({
    method: 'GET',
    url: `${CONVEX_URL}/api/last-outbound?phone=${encodeURIComponent(phone)}`,
    returnFullResponse: false
  });

  if (lastOutbound && lastOutbound.template_id) {
    template_id = lastOutbound.template_id;
  }
} catch (e) {
  // Continue without template_id
}

if (!template_id) {
  return [{
    json: {
      success: false,
      error: 'No template_id found for this phone',
      phone,
      classification,
      response_type
    }
  }];
}

// Call /api/template-response
try {
  const result = await this.helpers.httpRequest({
    method: 'POST',
    url: `${CONVEX_URL}/api/template-response`,
    body: {
      template_id: template_id,
      response_type: response_type
    },
    json: true,
    returnFullResponse: false
  });

  return [{
    json: {
      success: true,
      template_id,
      classification,
      response_type,
      convex_result: result
    }
  }];
} catch (e) {
  return [{
    json: {
      success: false,
      error: e.message,
      template_id,
      classification,
      response_type
    }
  }];
}

