// WRONG NUMBER OVERRIDE: Replaces AI-generated cold pitches with proper pivot responses
// The AI often ignores the 'wrong number' context and generates generic outreach

const input = $input.first().json;

// Get the original lead message
let messageText = '';
try {
  messageText = $('Parse Webhook').first().json.messageText || '';
} catch(e) {
  try {
    messageText = $('Build AI Context').first().json.messageText || '';
  } catch(e2) {
    messageText = '';
  }
}

const msgLower = messageText.toLowerCase().trim();

// Wrong number phrases
const wrongNumberPhrases = [
  'wrong number', 'wrong #', 'you have the wrong number',
  'u have the wrong number', 'this isnt my number',
  'this is not the right number', 'not my number',
  'wrong phone', 'dont have the right number'
];

const isWrongNumber = wrongNumberPhrases.some(function(phrase) {
  return msgLower.includes(phrase);
});

if (isWrongNumber) {
  // Canned responses that properly acknowledge wrong number and pivot
  const responses = [
    'ah ok! do u own a place in the area or know someone who might consider selling',
    'gotcha! do u own a place nearby or know anyone thinking abt selling',
    'oh my bad. do u own property in the area by chance',
    'sorry abt that. u own a place in the area or know someone looking to sell'
  ];
  const picked = responses[Math.floor(Math.random() * responses.length)];

  // Override the output field (what Validate AI Response reads)
  return [{ json: { ...input, output: picked, wrongNumberOverride: true } }];
}

// Not a wrong number - pass through unchanged
return [{ json: input }];

// DUPLICATE GUARD for main reply path
// Prevents sending the same or similar message twice to a lead

const input = $input.first().json;

// Get the reply text we are about to send
const replyText = input.reply || input.output || input.text || '';

if (!replyText) {
  return [{ json: { ...input, dedupPassed: true } }];
}

// Get last outbound messages
let recentOutbounds = [];
try {
  const messagesData = $('Get Last 5 Messages1').first().json;
  const allMessages = messagesData.data || [];
  recentOutbounds = allMessages
    .filter(function(m) { return m.direction === 'outbound'; })
    .slice(0, 5)
    .map(function(m) { return (m.text || '').toLowerCase().trim(); });
} catch (e) {
  // Fail open - allow send
  return [{ json: { ...input, dedupPassed: true } }];
}

const currentReply = replyText.toLowerCase().trim();

// Levenshtein similarity function
const similarity = function(a, b) {
  if (!a || !b) return 0;
  const longer = a.length > b.length ? a : b;
  const shorter = a.length > b.length ? b : a;
  if (longer.length === 0) return 1.0;
  const matrix = [];
  for (let i = 0; i <= shorter.length; i++) matrix[i] = [i];
  for (let j = 0; j <= longer.length; j++) matrix[0][j] = j;
  for (let i = 1; i <= shorter.length; i++) {
    for (let j = 1; j <= longer.length; j++) {
      if (shorter.charAt(i - 1) === longer.charAt(j - 1)) {
        matrix[i][j] = matrix[i - 1][j - 1];
      } else {
        matrix[i][j] = Math.min(matrix[i - 1][j - 1] + 1, matrix[i][j - 1] + 1, matrix[i - 1][j] + 1);
      }
    }
  }
  return (longer.length - matrix[shorter.length][longer.length]) / longer.length;
};

// Check against recent outbound messages
for (const prevOutbound of recentOutbounds) {
  if (!prevOutbound) continue;

  // Exact match
  if (currentReply === prevOutbound) {
    return [{ json: { blocked: true, reason: 'DUPLICATE: Exact match', originalReply: replyText } }];
  }

  // Same opening (first 30 chars)
  if (currentReply.length >= 25 && prevOutbound.length >= 25 &&
      currentReply.substring(0, 30) === prevOutbound.substring(0, 30)) {
    return [{ json: { blocked: true, reason: 'DUPLICATE: Same opening', originalReply: replyText } }];
  }

  // 75% similar
  const sim = similarity(currentReply, prevOutbound);
  if (sim > 0.75) {
    return [{ json: { blocked: true, reason: 'DUPLICATE: ' + Math.round(sim * 100) + '% similar', originalReply: replyText } }];
  }
}

// No duplicate found
return [{ json: { ...input, dedupPassed: true } }];

// RESPONSE COOLDOWN: Prevent duplicate automated responses
// Only blocks if THIS workflow already sent a reply recently
// Does NOT block first-time inbound replies after initial Text 1

var outboundMessages = [];
try {
  var messagesData = $('Get Last 5 Messages1').first().json;
  var allMessages = messagesData.data || [];

  // Collect all outbound messages
  for (var i = 0; i < allMessages.length; i++) {
    if (allMessages[i].direction === 'outbound' && allMessages[i].date_created) {
      outboundMessages.push(allMessages[i]);
    }
  }
} catch(e) {
  // Cannot get messages - allow processing (fail open)
  return $input.all();
}

// If there's only 1 outbound message, it's the initial Text 1
// from the import workflow — allow processing (first reply)
if (outboundMessages.length <= 1) {
  return $input.all();
}

// 2+ outbound messages means we already replied at least once
// Apply cooldown to prevent rapid duplicate responses
var recentOutbound = outboundMessages[0]; // newest first
if (recentOutbound && recentOutbound.date_created) {
  var outboundTime = new Date(recentOutbound.date_created);
  var now = new Date();
  var minutesSince = (now - outboundTime) / 1000 / 60;

  if (minutesSince < 3) {
    // BLOCK: We already responded less than 3 minutes ago
    return [];
  }
}

// Cooldown passed - continue with original data
return $input.all();

// Preserve the original Build AI Context payload while mirroring the inbound seller reply to InsulaCRM.
const input = $input.first().json;
try {
  const base = $env.INSULA_CRM_BASE_URL;
  const apiKey = $env.INSULA_CRM_API_KEY;
