      headers: { 'X-API-Key': apiKey },
      json: true
    });
    const lead = lookup?.data?.[0];
    if (lead?.id) {
      await this.helpers.httpRequest({
        method: 'POST',
        url: base + '/api/v1/activities',
        headers: {
          'X-API-Key': apiKey,
          'Content-Type': 'application/json',
          'Idempotency-Key': 'acquisition:inbound-sms:' + String(lead.id) + ':' + String(input.timestamp || Date.now()) + ':v1'
        },
        body: {
